package org.novasos.healthysv2.professional;
import static org.assertj.core.api.Assertions.*;
import java.time.*; import java.util.UUID; import org.junit.jupiter.api.Test;
class ProfessionalTests {
 @Test void buildsCompleteProfessionalAggregate(){var p=Professional.create(UUID.randomUUID(),"PRO-1","DOCTOR",null);p.addLicense("LIC-1","College",null,LocalDate.now(),LocalDate.now().plusYears(1),null);p.addSpeciality(UUID.randomUUID(),true);var a=p.addAssignment(UUID.randomUUID(),null,null,"Doctor","EMP-1",LocalDate.now(),null,null);a.addSchedule(1,LocalTime.of(8,0),LocalTime.of(16,0),30);a.addAvailability(Instant.now(),Instant.now().plusSeconds(3600),"CONSULTATION",null);assertThat(p.getLicenses()).hasSize(1);assertThat(p.getSpecialities()).singleElement().satisfies(s->assertThat(s.isPrimary()).isTrue());assertThat(p.getAssignments()).singleElement().satisfies(x->{assertThat(x.getSchedules()).hasSize(1);assertThat(x.getAvailabilities()).hasSize(1);});}
 @Test void keepsOnlyOnePrimarySpeciality(){var p=Professional.create(UUID.randomUUID(),"PRO-2","DOCTOR",null);var first=p.addSpeciality(UUID.randomUUID(),true);var second=p.addSpeciality(UUID.randomUUID(),true);assertThat(first.isPrimary()).isFalse();assertThat(second.isPrimary()).isTrue();}
 @Test void rejectsInconsistentRanges(){var p=Professional.create(UUID.randomUUID(),"PRO-3","NURSE",null);assertThatThrownBy(()->p.addLicense("L","A",null,LocalDate.now(),LocalDate.now().minusDays(1),null)).isInstanceOf(IllegalArgumentException.class);assertThatThrownBy(()->p.addAssignment(UUID.randomUUID(),null,UUID.randomUUID(),null,null,LocalDate.now(),null,null)).isInstanceOf(IllegalArgumentException.class);var a=p.addAssignment(UUID.randomUUID(),null,null,null,null,LocalDate.now(),null,null);assertThatThrownBy(()->a.addSchedule(1,LocalTime.NOON,LocalTime.NOON,30)).isInstanceOf(IllegalArgumentException.class);var instant=Instant.now();assertThatThrownBy(()->a.addAvailability(instant,instant,"CARE",null)).isInstanceOf(IllegalArgumentException.class);}
}
